   201	 * is (receipt, invoice, booking receipt) depends on how the guest is identified; the identification fields
   202	 * that do not apply are null.
   203	 */
   204	public record ReservationDocument(
   205	        String title,
   206	        long reservationId,
   207	        String guestName,
   208	        String guestCpf,
   209	        String companyCnpj,
   210	        String companyName,
   211	        String guestPassport,
   212	        String guestCountry,
   213	        int roomNumber,
   214	        RoomType roomType,
   215	        LocalDate checkIn,
   216	        LocalDate checkOut,
   217	        int nights,
   218	        BigDecimal subtotal,
   219	        BigDecimal discount,
   220	        BigDecimal total,
   221	        String text) {
   222	
   223	    public static ReservationDocument of(Reservation reservation, Room room) {
   224	        Identification identification = reservation.guest().identification();
   225	        DocumentLayout layout = DocumentLayout.of(identification);
   226	        ReservationDocument withoutText = new ReservationDocument(
   227	                layout.title(),
   228	                reservation.id(),
   229	                reservation.guest().name(),
   230	                identification.cpf(),
   231	                identification.companyCnpj(),
   232	                identification.companyName(),
   233	                identification.guestPassport(),
   234	                identification.guestCountry(),
   235	                room.number(),
   236	                room.type(),
   237	                reservation.checkIn(),
   238	                reservation.checkOut(),
   239	                reservation.price().nights(),
   240	                reservation.price().subtotal(),
   241	                reservation.price().discount(),
   242	                reservation.price().total(),
   243	                null);
   244	        return withoutText.withText(layout.text(withoutText));
   245	    }
   246	
   247	    private ReservationDocument withText(String text) {
   248	        return new ReservationDocument(
   249	                title, reservationId, guestName, guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
   250	                roomNumber, roomType, checkIn, checkOut, nights, subtotal, discount, total, text);
   251	    }
   252	}
