   257	import java.time.format.DateTimeFormatter;
   258	import java.util.Locale;
   259	
   260	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
   261	public final class TextFormat {
   262	
   263	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
   264	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   265	
   266	    private TextFormat() {
   267	    }
   268	
   269	    public static String money(BigDecimal amount) {
   270	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
   271	    }
   272	
   273	    public static String date(LocalDate date) {
   274	        return BRAZILIAN_DATE.format(date);
   275	    }
   276	}

